/**
 * mermaid-init.js
 * 
 * Dynamically detects Mermaid code blocks generated by Kramdown/Rouge,
 * replaces them with renderable .mermaid containers, and initializes
 * Mermaid.js via CDN ESM with typography matching the manuscript.
 */

(function() {
  'use strict';

  async function initMermaid() {
    // Locate all code blocks formatted with language-mermaid
    const codeCandidates = Array.from(document.querySelectorAll(
      'div.language-mermaid pre code, pre code.language-mermaid, code.language-mermaid, pre.language-mermaid'
    ));

    if (codeCandidates.length === 0) return;

    const processedContainers = new Set();
    const blocksToRender = [];

    codeCandidates.forEach(codeElem => {
      // Find the outermost container generated by Kramdown / Rouge
      const container = codeElem.closest('.highlighter-rouge') || 
                        codeElem.closest('div.language-mermaid') || 
                        codeElem.closest('pre') || 
                        codeElem;

      if (!container || processedContainers.has(container)) return;
      processedContainers.add(container);

      const rawCode = codeElem.textContent.trim();
      blocksToRender.push({ container, rawCode });
    });

    if (blocksToRender.length === 0) return;

    // Transform code containers into .mermaid elements
    blocksToRender.forEach((item, idx) => {
      const wrapper = document.createElement('div');
      wrapper.className = 'mermaid';
      wrapper.id = 'mermaid-diagram-' + (idx + 1);
      wrapper.textContent = item.rawCode;
      item.container.parentNode.replaceChild(wrapper, item.container);
    });

    try {
      const { default: mermaid } = await import('https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.esm.min.mjs');

      const isDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;

      mermaid.initialize({
        startOnLoad: false,
        theme: isDark ? 'dark' : 'neutral',
        fontFamily: '"EB Garamond", Garamond, Georgia, serif',
        themeVariables: isDark ? {
          fontFamily: '"EB Garamond", Garamond, Georgia, serif',
          darkMode: true,
          background: '#272629',
          primaryColor: '#363439',
          primaryBorderColor: '#6e6255',
          primaryTextColor: '#ece3d2',
          lineColor: '#a89c89'
        } : {
          fontFamily: '"EB Garamond", Garamond, Georgia, serif',
          background: '#fcfbf8',
          primaryColor: '#f7f4ed',
          primaryBorderColor: '#b0a48a',
          primaryTextColor: '#2c251e',
          lineColor: '#5c5245'
        },
        securityLevel: 'loose'
      });

      await mermaid.run({
        querySelector: '.mermaid'
      });
    } catch (err) {
      console.error('Failed to initialize or render Mermaid diagrams:', err);
    }
  }

  function tagGenerationNotes() {
    document.querySelectorAll('article p').forEach(p => {
      if (p.textContent.trim().startsWith('This summary was generated by')) {
        p.classList.add('generation-note');
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      tagGenerationNotes();
      initMermaid();
    });
  } else {
    tagGenerationNotes();
    initMermaid();
  }
})();
